-- Extended vw_ticketsalesreport: adds the `...Sold` columns the redesigned
-- dashboard needs (SUM of rows per category, i.e. the checked-in CASE without
-- the CheckedInDate condition) plus the current-fixture filter. Run after
-- migration.sql (which creates dashboard_current_fixture).
--
-- New columns: SeasonTicketsSold, WalkUpSold, BDS1Sold..BDS9Sold,
-- Alpha1Sold..Alpha4Sold, OakbankSold, AllSold (all rows), AllCheckedIn
-- (all checked-in rows incl. comps -> used to derive the Other bucket).

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_ticketsalesreport` AS
select sum((case when ((not((`ticketco_matchsales_live`.`TicketType` like '%comp%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%carer'))) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `TotalCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `WalkUpCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%') and ((`ticketco_matchsales_live`.`CheckedInOperator` = '3299870') or (`ticketco_matchsales_live`.`CheckedInOperator` = '3299872')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `AwayWalkUpCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%') and ((`ticketco_matchsales_live`.`CheckedInOperator` <> '3299870') or (`ticketco_matchsales_live`.`CheckedInOperator` <> '3299872')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `HomeWalkUpCheckedIn`,sum((case when ((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and (`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%') and (not((`ticketco_matchsales_live`.`TicketType` like '%comp%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%carer%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%other%'))) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `OnlineCheckedIn`,sum((case when ((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and (`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%') and (not((`ticketco_matchsales_live`.`TicketType` like '%comp%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%carer%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%other%')))) then 1 else 0 end)) AS `OnlineSold`,sum((case when ((`ticketco_matchsales_live`.`ticketcotickettype` like '%season%') and (not((`ticketco_matchsales_live`.`TicketType` like '%comp%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%carer'))) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `SeasonTicketsCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`TicketType` like '%comp%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `CompsCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`TicketType` like '%AWAY%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `AwayCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`TicketType` like '%home%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `HomeCheckedIn`,sum((case when ((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and (`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%') and (`ticketco_matchsales_live`.`TicketType` like '%away%')) then 1 else 0 end)) AS `AwaySold`,sum((case when ((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and (`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%') and (`ticketco_matchsales_live`.`TicketType` like '%home%')) then 1 else 0 end)) AS `HomeSold`,sum((case when (`ticketco_matchsales_live`.`TicketType` like '%Other%') then `ticketco_matchsales_live`.`QtySold` else 0 end)) AS `othersold`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 1 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS1CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 2 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS2CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 3 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS3CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 4 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS4CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 5 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS5CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 6 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS6CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 7 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS7CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 8 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS8CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 9 - BDS DIGITAL STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDS9CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%OAKBANK SERVICES TERRACE%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `OakbankCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%TERREGLES STREET TERRACE%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `TerreglesCheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 1 - MAIN STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `Alpha1CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 2 - MAIN STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `Alpha2CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 3 - MAIN STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `Alpha3CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`GroundArea` like '%SECTION 4 - MAIN STAND%') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `Alpha4CheckedIn`,sum((case when ((`ticketco_matchsales_live`.`CheckedInOperator` = '3169864') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `AlphaTS1`,sum((case when (((`ticketco_matchsales_live`.`CheckedInOperator` = '3169868') or (`ticketco_matchsales_live`.`CheckedInOperator` = '3169871')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `AlphaTS2`,sum((case when ((`ticketco_matchsales_live`.`CheckedInOperator` = '3299860') and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `EncTS1`,sum((case when (((`ticketco_matchsales_live`.`CheckedInOperator` = '3299862') or (`ticketco_matchsales_live`.`CheckedInOperator` = '3299865')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `TerraceTS1`,sum((case when (((`ticketco_matchsales_live`.`CheckedInOperator` = '3299867') or (`ticketco_matchsales_live`.`CheckedInOperator` = '3299868')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDSTS1`,sum((case when (((`ticketco_matchsales_live`.`CheckedInOperator` = '3299870') or (`ticketco_matchsales_live`.`CheckedInOperator` = '3299872')) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `BDSTS2`,max(`ticketco_matchsales_live`.`EventName`) AS `EventName`,sum((case when ((`ticketco_matchsales_live`.`ticketcotickettype` like '%season%') and (not((`ticketco_matchsales_live`.`TicketType` like '%comp%'))) and (not((`ticketco_matchsales_live`.`TicketType` like '%carer')))) then 1 else 0 end)) AS `SeasonTicketsSold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%') then 1 else 0 end)) AS `WalkUpSold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 1 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS1Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 2 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS2Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 3 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS3Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 4 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS4Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 5 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS5Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 6 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS6Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 7 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS7Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 8 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS8Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 9 - BDS DIGITAL STAND%') then 1 else 0 end)) AS `BDS9Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 1 - MAIN STAND%') then 1 else 0 end)) AS `Alpha1Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 2 - MAIN STAND%') then 1 else 0 end)) AS `Alpha2Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 3 - MAIN STAND%') then 1 else 0 end)) AS `Alpha3Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%SECTION 4 - MAIN STAND%') then 1 else 0 end)) AS `Alpha4Sold`,sum((case when (`ticketco_matchsales_live`.`GroundArea` like '%OAKBANK SERVICES TERRACE%') then 1 else 0 end)) AS `OakbankSold`,sum(1) AS `AllSold`,sum((case when (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%') then 1 else 0 end)) AS `AllCheckedIn`,sum((case when ((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and ((`ticketco_matchsales_live`.`ticketcotickettype` is null) or (not((`ticketco_matchsales_live`.`ticketcotickettype` like '%season%')))) and ((`ticketco_matchsales_live`.`ticketcotickettype` is null) or (not((`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%'))) or (`ticketco_matchsales_live`.`TicketType` like '%comp%') or (`ticketco_matchsales_live`.`TicketType` like '%carer%') or (`ticketco_matchsales_live`.`TicketType` like '%other%'))) then 1 else 0 end)) AS `OtherBucketSold`,sum((case when (((not((`ticketco_matchsales_live`.`GroundArea` like '%WALK-UP%'))) and ((`ticketco_matchsales_live`.`ticketcotickettype` is null) or (not((`ticketco_matchsales_live`.`ticketcotickettype` like '%season%')))) and ((`ticketco_matchsales_live`.`ticketcotickettype` is null) or (not((`ticketco_matchsales_live`.`ticketcotickettype` like '%ticket%'))) or (`ticketco_matchsales_live`.`TicketType` like '%comp%') or (`ticketco_matchsales_live`.`TicketType` like '%carer%') or (`ticketco_matchsales_live`.`TicketType` like '%other%'))) and (`ticketco_matchsales_live`.`CheckedInDate` like '%-%-%T%')) then 1 else 0 end)) AS `OtherBucketCheckedIn` from `ticketco_matchsales_live` where (`ticketco_matchsales_live`.`fixtureid` = (select `dashboard_current_fixture`.`fixtureid` from `dashboard_current_fixture` limit 1));
